SELECT * FROM ecommerce.customers;

# “What is the total sales amount generated by each customer?”
select c.customer_id, sum(oi.price) as total_sales from customers c join orders o on c.customer_id = o.customer_id 
 join order_items oi on oi.order_id = o.order_id group by c.customer_id

b

#Show the first 10 customers from the state of São Paulo (SP), sorted alphabetically by city.
select customer_id, customer_city, customer_state from customers WHERE CUSTOMER_STATE = "SP" ORDER BY CUSTOMER_CITY ASC  LIMIT 10

SELECT COUNT(CUSTOMER_ID) FROM CUSTOMERS
SELECT COUNT(CUSTOMER_ID) AS SP_CUSTOMERS FROM CUSTOMERS WHERE CUSTOMER_STATE = 'SP'

select customer_state,count(*) as Customer_in_each_state from customers group by customer_state

#Which states have more than 1,000 customers?
select customer_state, count(customer_state) as total_customer from customers group by customer_state having total_customer > 1000

#Show each order along with the city and state of the customer who placed it.
select  o.order_id, c.customer_city, c.customer_state from orders o join customers c on c.customer_id = o.customer_id

# "Show all customers and the orders they have placed, including customers who have never placed an order."
select o.order_id ,c.customer_id, c.customer_city from customers c right join orders o on c.customer_id = o.customer_id 

#  finding customers who have never placed an order.
select c.customer_id , c.customer_city from customers c left join orders o on c.customer_id = o.customer_id where o.order_id is null

# “What are the different customer states present in our e-commerce data?”
select distinct customer_state from customers     
