# Some customers may have missing city/state information. How can we replace a NULL value with a default value
select customer_id, coalesce(customer_city, 'UNKNOWN ') as customer_city from customers
-------------------------------------------------------------------------------------------------------------------------------------------------------------
# “Create a customer label combining their city and state.”
SELECT CUSTOMER_ID, CONCAT(CUSTOMER_CITY," ," ,CUSTOMER_STATE) AS CUSTOMER_LABEL FROM CUSTOMERS

# MAKING ALL THE RECORDS IN THE MENTIONED COLUMN IN UPPER CASE 
SELECT CUSTOMER_ID, UPPER(CUSTOMER_CITY) AS CUSTOMER_CITY  FROM CUSTOMERS 
----------------------------------------------------------------------------------------------------------------------------------------------------------
# “Are there any missing customer city in our customer data?”
select count(*) as missing_customer from customers where customer_city is  null
# “Which customer cities appear more than once in our dataset?”
select customer_city , count(*) as city_count from customers group by customer_city having count(*) > 1

# “Are there customer cities with accidental leading/trailing spaces?”
select customer_city, trim(customer_city) as proper_city from customers 

# “Which customer states have more than 1,000 customers?”
select customer_state, count(*) as total_customer from customers group by customer_state having count(*)  > 1000

# “Which customers have never placed an order?”
select c.customer_id, o.order_purchase_timestamp from customers c left join orders o on c.customer_id = o.customer_id 
where order_purchase_timestamp is null




